export const updateDocumentBodyMarketRegExp = new RegExp('^[a-z][a-z0-9-]{1,15}$');
export const updateDocumentBodyLocaleRegExp = new RegExp('^(?:und|[a-z]{2}(?:-[A-Z]{2})?)$');
export const updateDocumentBodyRevisionNumberMultipleOf = 1;



